window.BOOK={"key":"kalwadhaniyya","app":"mutoon-kalwadhaniyya","lsk":"mutoon_kalwadhaniyya_v1","prefix":"ka_","title":"دالية الكلوذاني","sub":"العقيدة · أبو الخطاب الكلوذاني (ت ٥١٠هـ) · ٤٥ بيتًا","poems":[{"id":"kalwadhaniyya","title":"دالية الكلوذاني","nazim":"أبو الخطاب محفوظ بن أحمد الكلوذاني","death":"ت ٥١٠هـ","meter":"الكامل","source":"المكتبة الشاملة: شرح القصيدة الدالية للكلوذاني، عبد الرحمن البراك، عناية ياسر العسكر (دار ابن الجوزي، ١٤٣٠هـ)","srcUrl":"https://ketabonline.com/ar/books/2384","note":"نص الأبيات المشكول من «شرح القصيدة الدالية» للشيخ عبد الرحمن البراك (٤٥ بيتًا)، قوبل كلمةً كلمةً بسكربت بنص «شرح دالية أبي الخطاب الكلوذاني» لهاني الجبير (٥٢ بيتًا، بزيادة سبعة أبيات لم يثبتها الشرح الأول). أُكمل ما تركته النشرة بلا شكل (قالوا، قلتُ، حرف الروي ونحوها)، وكل شطر موزون على الكامل.","verses":[["دَعْ عَنْكَ تَذْكَارَ الْخَلِيطِ الْمُنْجِدِ","وَالشَّوْقَ نَحْوَ الْآنِسَاتِ الْخُرَّدِ"],["وَالنَّوْحَ فِي أَطْلَالِ سُعْدَى إِنَّمَا","تَذْكَارُ سُعْدَى شُغْلُ مَنْ لَمْ يَسْعَدِ"],["وَاسْمَعْ مَقَالِي إِنْ أَرَدْتَ تَخَلُّصًا","يَوْمَ الْحِسَابِ وَخُذْ بِهَذَا تَهْتَدِي"],["وَاقْصِدْ فَإِنِّي قَدْ قَفَيْتُ مُوَفَّقًا","نَهْجَ ابْنِ حَنْبَلٍ الْإِمَامِ الْأَوْحَدِ"],["خَيْرِ الْبَرِيَّةِ بَعْدَ صَحْبِ مُحَمَّدٍ","وَالتَّابِعِينَ إِمَامِ كُلِّ مُوَحِّدِ"],["ذِي الْعِلْمِ وَالرَّأْيِ الْأَصِيلِ وَمَنْ حَوَى","شَرَفًا عَلَا فَوْقَ السُّهَا وَالْفَرْقَدِ"],["وَاعْلَمْ بِأَنِّي قَدْ نَظَمْتُ مَسَائِلًا","لَمْ آلُ فِيهَا النُّصْحَ غَيْرَ مُقَلِّدِ"],["وَأَجَبْتُ عَنْ تَسْآلِ كُلِّ مُهَذَّبٍ","ذِي صَوْلَةٍ يَوْمَ الْجِدَالِ مُسَوَّدِ"],["هَجَرَ الرُّقَادَ وَبَاتَ سَاهِرَ لَيْلِهِ","ذِي هِمَّةٍ لَا يَسْتَلِذُّ بِمَرْقَدِ"],["قَوْمٌ طَعَامُهُمُ دِرَاسَةُ عِلْمِهِمْ","يَتَسَابَقُونَ إِلَى الْعُلَا وَالسُّؤْدَدِ"],["قَالُوا بِمَا عَرَفَ الْمُكَلَّفُ رَبَّهُ","فَأَجَبْتُ بِالنَّظَرِ الصَّحِيحِ الْمُرْشِدِ"],["قَالُوا فَهَلْ رَبُّ الْخَلَائِقِ وَاحِدٌ","قُلْتُ الْكَمَالُ لِرَبِّنَا الْمُتَفَرِّدِ"],["قَالُوا فَهَلْ تَصِفُ الْإِلَهَ أَبِنْ لَنَا","قُلْتُ الصِّفَاتُ لِذِي الْجَلَالِ السَّرْمَدِ"],["قَالُوا فَهَلْ تِلْكَ الصِّفَاتُ قَدِيمَةٌ","كَالذَّاتِ قُلْتُ كَذَاكَ لَمْ تَتَجَدَّدِ"],["قَالُوا فَهَلْ لِلَّهِ عِنْدَكَ مُشْبِهٌ","قُلْتُ الْمُشَبِّهُ فِي الْجَحِيمِ الْمُوصَدِ"],["قَالُوا فَأَنْتَ تَرَاهُ جِسْمًا قُلْ لَنَا","قُلْتُ الْمُجَسِّمُ عِنْدَنَا كَالْمُلْحِدِ"],["قَالُوا فَهَلْ هُوَ فِي الْأَمَاكِنِ كُلِّهَا","قُلْتُ الْأَمَاكِنُ لَا تُحِيطُ بِسَيِّدِي"],["قَالُوا أَتَزْعُمُ أَنْ عَلَى الْعَرْشِ اسْتَوَى","قُلْتُ الصَّوَابُ كَذَاكَ أَخْبَرَ سَيِّدِي"],["قَالُوا فَمَا مَعْنَى اسْتِوَاهُ أَبِنْ لَنَا","فَأَجَبْتُهُمْ هَذَا سُؤَالُ الْمُعْتَدِي"],["قَالُوا النُّزُولُ فَقُلْتُ نَاقِلُهُ لَنَا","قَوْمٌ هُمُ نَقَلُوا شَرِيعَةَ أَحْمَدِ"],["قَالُوا فَكَيْفَ نُزُولُهُ فَأَجَبْتُهُمْ","لَمْ يُنْقَلِ التَّكْيِيفُ لِي فِي مُسْنَدِ"],["قَالُوا فَيُنْظَرُ بِالْعُيُونِ أَبِنْ لَنَا","فَأَجَبْتُ رُؤْيَتُهُ لِمَنْ هُوَ مُهْتَدِي"],["قَالُوا فَهَلْ لِلَّهِ عِلْمٌ قُلْتُ مَا","مِنْ عَالِمٍ إِلَّا بِعِلْمٍ مُرْتَدِ"],["قَالُوا تَصِفْهُ بِأَنَّهُ مُتَكَلِّمٌ","قُلْتُ السُّكُوتُ نَقِيصَةٌ بِالسَّيِّدِ"],["قَالُوا فَمَا الْقُرْآنُ قُلْتُ كَلَامُهُ","مِنْ غَيْرِ مَا حَدَثٍ وَغَيْرِ تَجَدُّدِ"],["قَالُوا الَّذِي نَتْلُوهُ قُلْتُ كَلَامُهُ","لَا رَيْبَ فِيهِ عِنْدَ كُلِّ مُوَحِّدِ"],["قَالُوا فَأَفْعَالُ الْعِبَادِ فَقُلْتُ مَا","مِنْ خَالِقٍ غَيْرِ الْإِلَهِ الْأَمْجَدِ"],["قَالُوا فَهَلْ فِعْلُ الْقَبِيحِ مُرَادُهُ","قُلْتُ الْإِرَادَةُ كُلُّهَا لِلسَّيِّدِ"],["لَوْ لَمْ يُرِدْهُ وَكَانَ كَانَ نَقِيصَةً","سُبْحَانَهُ عَنْ أَنْ يُعَجِّزَهُ الرَّدِي"],["قَالُوا فَمَا الْإِيمَانُ قُلْتُ مُجَاوِبًا","عَمَلٌ وَتَصْدِيقٌ بِغَيْرِ تَبَلُّدِ"],["قَالُوا فَمَنْ بَعْدَ النَّبِيِّ خَلِيفَةٌ","قُلْتُ الْمُوَحِّدُ قَبْلَ كُلِّ مُوَحِّدِ"],["حَامِيهِ فِي يَوْمِ الْعَرِيشِ وَمَنْ لَهُ","فِي الْغَارِ أَسْعَدَ يَا لَهُ مِنْ مُسْعِدِ"],["قَالُوا فَمَنْ ثَانِي أَبِي بَكْرِ الرِّضَا","قُلْتُ الْإِمَارَةُ فِي الْإِمَامِ الْأَزْهَدِ"],["فَارُوقُ أَحْمَدَ وَالْمُهَذَّبُ بَعْدَهُ","سَنَدُ الشَّرِيعَةِ بِاللِّسَانِ وَبِالْيَدِ"],["قَالُوا فَثَالِثُهُمْ فَقُلْتُ مُجَاوِبًا","مَنْ بَايَعَ الْمُخْتَارُ عَنْهُ بِالْيَدِ"],["صِهْرُ النَّبِيِّ عَلَى ابْنَتَيْهِ وَمَنْ حَوَى","فَضْلَيْنِ فَضْلَ تِلَاوَةٍ وَتَهَجُّدِ"],["أَعْنِي ابْنَ عَفَّانَ الشَّهِيدَ وَمَنْ دُعِي","فِي النَّاسِ ذَا النُّورَيْنِ صِهْرَ مُحَمَّدِ"],["قَالُوا فَرَابِعُهُمْ فَقُلْتُ مُبَادِرًا","مَنْ حَازَ دُونَهُمُ أُخُوَّةَ أَحْمَدِ"],["زَوْجُ الْبَتُولِ وَخَيْرُ مَنْ وَطِئَ الْحَصَى","بَعْدَ الثَّلَاثَةِ وَالْكَرِيمُ الْمَحْتِدِ"],["أَعْنِي أَبَا الْحَسَنِ الْإِمَامَ وَمَنْ لَهُ","بَيْنَ الْأَنَامِ فَضَائِلٌ لَمْ تُجْحَدِ"],["وَلِإِبْنِ هِنْدٍ فِي الْفُؤَادِ مَحَبَّةٌ","وَمَوَدَّةٌ فَلَيَرْغَمَنَّ مُفَنِّدِي"],["ذَاكَ الْأَمِينُ الْمُجْتَبَى لِكِتَابَةِ الْـ","ـوَحْيِ الْمُنَزَّلِ ذُو التُّقَى وَالسُّؤْدَدِ"],["فَعَلَيْهِمُ وَعَلَى الصَّحَابَةِ كُلِّهِمْ","صَلَوَاتُ رَبِّهِمُ تَرُوحُ وَتَغْتَدِي"],["إِنِّي لَأَرْجُو أَنْ أَفُوزَ بِحُبِّهِمْ","وَبِمَا اعْتَقَدْتُ مِنَ الشَّرِيعَةِ فِي غَدِ"],["قَالُوا أَبَانَ الْكَلْوَذَانِيُّ الْهُدَى","قُلْتُ الَّذِي فَوْقَ السَّمَاءِ مُؤَيِّدِي"]],"secs":{"1":"دالية الكلوذاني"}}],"sharh":false};
